export const TOTAL=12;
export const initial=()=>({chapter:0,week:0,cash:480,learning:0,bonds:0,plan:{stall:4,study:4,friends:4},history:[],baseline:null});
export function validPlan(p){return p&&Object.keys(p).length===3&&['stall','study','friends'].every(k=>Number.isInteger(p[k])&&p[k]>=0&&p[k]<=12)&&Object.values(p).reduce((a,b)=>a+b,0)===TOTAL;}
export function shift(plan,key,delta){if(!validPlan(plan)||!['stall','study','friends'].includes(key)||![2,-2].includes(delta))return plan;const next={...plan};if(delta<0){if(next[key]<2)return plan;const other=['stall','study','friends'].filter(k=>k!==key).sort((a,b)=>next[b]-next[a])[0];next[key]-=2;next[other]+=2;}else{const donor=['stall','study','friends'].filter(k=>k!==key).sort((a,b)=>next[b]-next[a])[0];if(next[donor]<2)return plan;next[key]+=2;next[donor]-=2;}return next;}
export function advance(s){if(s.chapter<2)return {...s,chapter:s.chapter+1};if(s.week>=4||!validPlan(s.plan))return s;const rain=s.week===1;const earned=s.plan.stall*15;const cost=60+(rain?120:0);const entry={week:s.week+1,plan:{...s.plan},rain,earned,cost};return {...s,week:s.week+1,cash:s.cash+earned-cost,learning:s.learning+s.plan.study,bonds:s.bonds+s.plan.friends,history:[...s.history,entry]};}
export function replay(s){if(s.week!==4)return s;return {...initial(),chapter:2,baseline:{cash:s.cash,learning:s.learning,bonds:s.bonds}};}
export function validSave(s){return s&&Number.isInteger(s.chapter)&&s.chapter>=0&&s.chapter<=2&&Number.isInteger(s.week)&&s.week>=0&&s.week<=4&&validPlan(s.plan)&&['cash','learning','bonds'].every(k=>Number.isFinite(s[k]))&&Array.isArray(s.history)&&s.history.length===s.week&&s.history.every((e,i)=>e.week===i+1&&validPlan(e.plan))&&(s.baseline===null||['cash','learning','bonds'].every(k=>Number.isFinite(s.baseline?.[k])));}
